/* Relay — operations control room
   Calm, high-density, neutral palette with a single accent. No gradients,
   no glass, no decorative rounding. Numeric alignment and clear severity
   states are prioritized over ornament. */

:root {
  --bg: #f2f3f5;
  --surface: #ffffff;
  --ink: #1c2025;
  --ink-2: #4b535d;
  --ink-3: #767f8a;
  --line: #dfe2e7;
  --line-strong: #c8ccd3;
  --rail: #20252c;
  --rail-ink: #aeb6c0;
  --accent: #2f6df0;
  --accent-hover: #2057cf;
  --accent-soft: #e8f0fe;
  --sev-critical: #c0342b;
  --sev-critical-bg: #fbe9e7;
  --sev-high: #b25a09;
  --sev-high-bg: #fbeed9;
  --sev-medium: #8a6d00;
  --sev-medium-bg: #f7f0d2;
  --sev-low: #3d6b52;
  --sev-low-bg: #e4efe8;
  --good: #2e7d52;
  --warn: #b25a09;
  --radius: 4px;
  --tabular: "SFMono-Regular", ui-monospace, "Cascadia Mono", "Segoe UI Mono", Menlo, Consolas, monospace;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 13px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

h1, h2, p { margin: 0; }

button, input, select { font: inherit; color: inherit; }

button { cursor: pointer; }

/* Focus: always visible for keyboard users. */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 2px;
}
/* Keep a visible outline for selected table rows too. */
tr[tabindex]:focus-visible { outline-offset: -2px; }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 8px; top: -48px; z-index: 50;
  background: var(--accent); color: #fff; padding: 8px 14px;
  border-radius: var(--radius); text-decoration: none;
}
.skip-link:focus { top: 8px; }

/* ---- Shell ---- */
.app { display: flex; min-height: 100vh; }

.rail {
  width: 184px; flex: 0 0 184px;
  background: var(--rail); color: var(--rail-ink);
  display: flex; flex-direction: column;
  position: sticky; top: 0; height: 100vh;
}
.rail-brand {
  margin: 14px 14px 6px; height: 34px; width: 34px;
  display: grid; place-items: center;
  background: var(--accent); color: #fff;
  font-weight: 700; font-size: 16px; border-radius: var(--radius);
}
.rail-items { list-style: none; margin: 10px 0 0; padding: 0 8px; }
.rail-btn {
  width: 100%; display: flex; align-items: center; gap: 12px;
  padding: 9px 10px; margin-bottom: 2px;
  background: transparent; color: var(--rail-ink);
  border: 0; border-radius: var(--radius); text-align: left;
  font-size: 13px; font-weight: 500;
}
.rail-btn svg { width: 18px; height: 18px; flex: 0 0 18px; }
.rail-btn:hover { background: #2b323b; color: #fff; }
.rail-btn[aria-current="page"] {
  background: #333b45; color: #fff;
  box-shadow: inset 3px 0 0 var(--accent);
}
.rail-btn:focus-visible { outline-color: #8fb4ff; }
.rail-foot {
  margin: auto 14px 14px; height: 30px; width: 30px;
  display: grid; place-items: center; font-size: 11px; font-weight: 700;
  border: 1px solid #454e58; border-radius: 50%; color: var(--rail-ink);
  letter-spacing: .5px;
}

.main { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; }

/* ---- Top status bar ---- */
.topbar {
  height: 46px; flex: 0 0 46px;
  background: var(--surface); border-bottom: 1px solid var(--line);
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 20px; gap: 12px;
  position: sticky; top: 0; z-index: 10;
}
.tb-group { display: flex; align-items: center; gap: 10px; min-width: 0; }
.tb-status { font-weight: 600; color: var(--ink); white-space: nowrap; }
.tb-muted { color: var(--ink-3); white-space: nowrap; }
.tb-muted strong { color: var(--ink-2); font-variant-numeric: tabular-nums; }
.tb-sep { width: 1px; height: 16px; background: var(--line-strong); }
.chip {
  font-family: var(--tabular); font-size: 11px; letter-spacing: .3px;
  background: #eef0f3; color: var(--ink-2);
  border: 1px solid var(--line); border-radius: var(--radius);
  padding: 3px 8px; white-space: nowrap;
}
.live { display: inline-flex; align-items: center; gap: 6px; color: var(--good); font-weight: 600; font-size: 12px; }
.live-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--good); }
.tb-clock { font-family: var(--tabular); font-size: 12px; color: var(--ink-2); font-variant-numeric: tabular-nums; white-space: nowrap; }

.health-dot { width: 8px; height: 8px; border-radius: 50%; flex: 0 0 8px; }
.health--ok { background: var(--good); }
.health--warn { background: var(--warn); box-shadow: 0 0 0 3px #f3e3cf; }
.health--down { background: var(--sev-critical); box-shadow: 0 0 0 3px var(--sev-critical-bg); }

/* ---- Workspace ---- */
.workspace { padding: 22px 24px 40px; width: 100%; max-width: 1360px; margin: 0 auto; }

.page-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; margin-bottom: 16px; }
.page-head h1 { font-size: 18px; font-weight: 650; letter-spacing: -.2px; }
.page-sub { color: var(--ink-3); font-size: 12px; }
.range-note { font-family: var(--tabular); font-size: 11px; color: var(--ink-3); white-space: nowrap; }

/* ---- Metrics ---- */
.metrics {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px;
  margin-bottom: 16px;
}
.metric {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--radius); padding: 13px 15px 14px;
  border-top: 2px solid var(--line-strong);
}
.metric.is-flagged { border-top-color: var(--warn); }
.metric-label { color: var(--ink-3); font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: .6px; }
.metric-value {
  font-size: 25px; font-weight: 650; letter-spacing: -.6px; line-height: 1.15;
  margin: 7px 0 6px; font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.metric-trend { display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; }
.trend-up { color: var(--good); }
.trend-down { color: var(--good); }
.trend-bad { color: var(--sev-critical); }
.trend-arrow { font-family: var(--tabular); font-size: 12px; }
.metric-context { color: var(--ink-3); }

/* ---- Panels ---- */
.panel {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--radius);
}
.panel-head {
  display: flex; align-items: baseline; justify-content: space-between; gap: 10px;
  padding: 12px 15px; border-bottom: 1px solid var(--line);
}
.panel-title { font-size: 13px; font-weight: 650; }
.panel-note { color: var(--ink-3); font-size: 11px; }

/* ---- Chart ---- */
.chart-panel { margin-bottom: 16px; }
.chart-body { padding: 12px 15px 4px; }
.chart-svg { display: block; width: 100%; height: auto; }
.chart-caption { color: var(--ink-3); font-size: 11px; margin-top: 4px; }
.grid-line { stroke: #eaecf0; stroke-width: 1; }
.axis-label { fill: var(--ink-3); font-size: 9px; font-family: var(--tabular); }
.chart-area { fill: #eef3fd; }
.chart-line { fill: none; stroke: var(--accent); stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
.chart-dot { fill: var(--surface); stroke: var(--accent); stroke-width: 2; }
.chart-peak-label { fill: var(--ink-2); font-size: 10px; font-weight: 600; font-family: var(--tabular); }
.chart-stats {
  display: flex; gap: 26px; flex-wrap: wrap;
  padding: 10px 15px 13px;
  border-top: 1px solid var(--line);
}
.cstat-label { color: var(--ink-3); font-size: 10.5px; text-transform: uppercase; letter-spacing: .5px; }
.cstat-value { font-family: var(--tabular); font-variant-numeric: tabular-nums; font-size: 14px; font-weight: 600; }

/* ---- Lower layout ---- */
.lower {
  display: grid; grid-template-columns: minmax(0, 1fr) 330px; gap: 16px;
  align-items: start;
}

/* ---- Filters ---- */
.filters {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding: 10px 15px; border-bottom: 1px solid var(--line);
}
.filters input[type="search"], .filters select {
  background: #fff; border: 1px solid var(--line-strong);
  border-radius: var(--radius); padding: 6px 9px; font-size: 12px;
  height: 32px;
}
.filters input[type="search"] { flex: 1 1 200px; min-width: 140px; }
.filters select { flex: 0 0 auto; }
.filters input::placeholder { color: var(--ink-3); }
.btn-ghost {
  background: transparent; border: 1px solid var(--line-strong);
  border-radius: var(--radius); padding: 6px 11px; height: 32px;
  font-size: 12px; color: var(--ink-2); font-weight: 500;
}
.btn-ghost:hover { background: #eef0f3; color: var(--ink); }
.result-count { font-family: var(--tabular); font-size: 11px; color: var(--ink-3); margin-left: auto; white-space: nowrap; }

/* ---- Incident table ---- */
.table-wrap { overflow-x: auto; }
.incidents-table { width: 100%; border-collapse: collapse; }
.incidents-table th {
  text-align: left; font-size: 10.5px; font-weight: 600;
  text-transform: uppercase; letter-spacing: .5px; color: var(--ink-3);
  padding: 9px 12px; border-bottom: 1px solid var(--line);
  white-space: nowrap; background: #fafbfc;
}
.incidents-table td {
  padding: 10px 12px; border-bottom: 1px solid #eef0f2;
  vertical-align: middle; white-space: nowrap;
}
.incidents-table tbody tr { cursor: pointer; }
.incidents-table tbody tr:hover { background: #f7f9fc; }
.incidents-table tbody tr.is-selected { background: var(--accent-soft); box-shadow: inset 3px 0 0 var(--accent); }
.incidents-table tbody tr:last-child td { border-bottom: 0; }
.cell-id { font-family: var(--tabular); font-size: 11.5px; color: var(--ink-3); }
.cell-title { display: block; font-size: 12px; font-weight: 550; color: var(--ink); margin-top: 1px; }
.cell-service { font-family: var(--tabular); font-size: 11.5px; color: var(--ink-2); }
.col-age, .cell-age { text-align: right; font-family: var(--tabular); font-variant-numeric: tabular-nums; }
.cell-owner { color: var(--ink-2); }
.cell-owner.is-unassigned { color: var(--warn); font-style: italic; }

.sev {
  display: inline-block; font-size: 10.5px; font-weight: 650;
  text-transform: uppercase; letter-spacing: .4px;
  padding: 2px 7px; border-radius: 3px;
  border: 1px solid transparent;
}
.sev::before { content: ""; display: inline-block; width: 6px; height: 6px; border-radius: 50%; margin-right: 6px; background: currentColor; vertical-align: 1px; }
.sev--critical { color: var(--sev-critical); background: var(--sev-critical-bg); border-color: #f0d3cf; }
.sev--high { color: var(--sev-high); background: var(--sev-high-bg); border-color: #f0dcc0; }
.sev--medium { color: var(--sev-medium); background: var(--sev-medium-bg); border-color: #e9dfae; }
.sev--low { color: var(--sev-low); background: var(--sev-low-bg); border-color: #cfe0d5; }

.status { display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--ink-2); }
.status-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--ink-3); flex: 0 0 7px; }
.status--investigating .status-dot { background: var(--sev-critical); }
.status--open .status-dot { background: var(--warn); }
.status--monitoring .status-dot { background: var(--accent); }
.status--acknowledged .status-dot { background: #7a6bd0; }
.status--resolved .status-dot { background: var(--good); }

.empty { padding: 34px 18px; text-align: center; color: var(--ink-3); font-size: 12px; }
.empty-title { font-weight: 600; color: var(--ink-2); font-size: 13px; margin-bottom: 4px; }
.empty .btn-ghost { margin-top: 12px; }

/* ---- Detail panel ---- */
.detail-panel { position: sticky; top: 62px; }
.detail-body { padding: 15px; }
.detail-kicker { font-family: var(--tabular); font-size: 11px; color: var(--ink-3); }
.detail-title { font-size: 15px; font-weight: 650; line-height: 1.35; margin: 4px 0 10px; }
.detail-sev-row { display: flex; align-items: center; gap: 8px; margin-bottom: 14px; }
.detail-grid { border-top: 1px solid var(--line); }
.detail-row {
  display: flex; justify-content: space-between; gap: 12px;
  padding: 9px 0; border-bottom: 1px solid #eef0f2;
}
.detail-row dt { color: var(--ink-3); font-size: 11.5px; }
.detail-row dd { margin: 0; font-size: 12px; font-weight: 550; font-family: var(--tabular); text-align: right; }
.detail-row dd.is-unassigned { color: var(--warn); font-style: italic; }
.detail-note {
  background: #fafbfc; border: 1px solid var(--line); border-left: 2px solid var(--accent);
  border-radius: var(--radius); padding: 9px 11px; margin: 14px 0;
  font-size: 11.5px; color: var(--ink-2);
}
.detail-actions { display: flex; gap: 8px; margin-top: 16px; }
.btn-primary {
  flex: 1; background: var(--accent); color: #fff; border: 1px solid var(--accent);
  border-radius: var(--radius); padding: 9px 12px; font-size: 12.5px; font-weight: 600;
}
.btn-primary:hover:not(:disabled) { background: var(--accent-hover); }
.btn-primary:disabled { background: #eef0f3; border-color: var(--line); color: var(--ink-3); cursor: default; }
.ack-msg { font-size: 11.5px; color: var(--good); font-weight: 600; margin-top: 10px; }
.detail-placeholder { padding: 40px 18px; text-align: center; color: var(--ink-3); }
.detail-placeholder svg { width: 30px; height: 30px; color: var(--line-strong); margin-bottom: 8px; }

/* ---- Responsive ---- */
@media (max-width: 1080px) {
  .metrics { grid-template-columns: repeat(2, 1fr); }
  .lower { grid-template-columns: minmax(0, 1fr); }
  .detail-panel { position: static; }
}

@media (max-width: 720px) {
  .rail { width: 56px; flex-basis: 56px; }
  .rail-brand { margin: 12px auto 6px; }
  .rail-label { display: none; }
  .rail-items { padding: 0 6px; }
  .rail-btn { justify-content: center; padding: 11px 0; }
  .rail-foot { margin: auto auto 12px; }
  .workspace { padding: 16px 14px 32px; }
  .topbar { padding: 0 12px; }
}

/* 390px and below: no horizontal page scroll, single-column metrics. */
@media (max-width: 480px) {
  .page-head { align-items: flex-start; flex-direction: column; gap: 4px; }
  .metrics { grid-template-columns: 1fr 1fr; gap: 8px; }
  .metric { padding: 10px 11px 11px; }
  .metric-value { font-size: 20px; }
  .tb-group.tb-right .chip, .tb-group.tb-right .tb-clock { display: none; }
  .tb-muted { display: none; }
  .tb-sep { display: none; }
  .filters { gap: 6px; }
  .filters select { flex: 1 1 calc(50% - 6px); }
  .result-count { flex-basis: 100%; margin-left: 0; }
  .incidents-table th, .incidents-table td { padding: 9px 8px; }
  .chart-stats { gap: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  * { scroll-behavior: auto !important; }
}

/* Relay — operations control room
 * No frameworks, no build, no network. The dashboard is seeded inline from
 * DATA.json (the object below is a verbatim copy of that file) so the page
 * works when opened directly via file:// without any fetch/XHR request.
 */
(function () {
  "use strict";

  var DATA = {
    "metrics": [
      {"label":"Events / min","value":"18,420","change":"+8.2%","direction":"up"},
      {"label":"P95 latency","value":"184 ms","change":"−12 ms","direction":"down"},
      {"label":"Error rate","value":"0.37%","change":"+0.08 pp","direction":"up"},
      {"label":"Queue depth","value":"2,841","change":"−19%","direction":"down"}
    ],
    "throughput": [31,28,24,22,20,23,34,48,62,71,76,73,68,72,80,84,79,75,82,88,77,63,52,41],
    "incidents": [
      {"id":"INC-2841","severity":"critical","service":"payments-api","age":"12m","owner":"M. Chen","status":"investigating","title":"Card authorization timeouts"},
      {"id":"INC-2839","severity":"high","service":"event-router","age":"31m","owner":"Unassigned","status":"open","title":"EU retry queue growth"},
      {"id":"INC-2837","severity":"medium","service":"search-index","age":"1h 08m","owner":"A. Silva","status":"monitoring","title":"Index freshness outside SLO"},
      {"id":"INC-2832","severity":"low","service":"webhooks","age":"3h 42m","owner":"R. Patel","status":"open","title":"Elevated partner delivery lag"}
    ]
  };

  /* State is a working copy so acknowledge mutates real state. */
  var incidents = DATA.incidents.map(function (i) {
    return {
      id: i.id, severity: i.severity, service: i.service, age: i.age,
      owner: i.owner, status: i.status, title: i.title, ackAt: null
    };
  });

  var selectedId = null;
  var filters = { search: "", severity: "all", status: "all" };

  var $ = function (id) { return document.getElementById(id); };
  var esc = function (s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  };

  /* ---------- Metrics ---------- */
  function renderMetrics() {
    /* Context + "bad direction" logic: up is bad for error rate, good for
       throughput; down is good everywhere else. */
    var badForUp = { "Error rate": true };
    var context = {
      "Events / min": "vs. prior 24h",
      "P95 latency": "vs. prior 24h",
      "Error rate": "vs. prior 24h",
      "Queue depth": "vs. prior 24h"
    };
    var html = DATA.metrics.map(function (m) {
      var isBad = m.direction === "up" && badForUp[m.label];
      var flagged = isBad || m.label === "Error rate";
      var arrow = m.direction === "up" ? "▲" : "▼";
      var cls = isBad ? "trend-bad" : (m.direction === "up" ? "trend-up" : "trend-down");
      return '<article class="metric' + (flagged ? ' is-flagged' : '') + '">' +
        '<div class="metric-label">' + esc(m.label) + '</div>' +
        '<div class="metric-value">' + esc(m.value) + '</div>' +
        '<div class="metric-trend ' + cls + '">' +
          '<span class="trend-arrow" aria-hidden="true">' + arrow + '</span>' +
          '<span>' + esc(m.change) + '</span>' +
          '<span class="metric-context">' + esc(context[m.label]) + '</span>' +
        '</div>' +
      '</article>';
    }).join("");
    $("overview").innerHTML = html;
  }

  /* ---------- 24h throughput chart (inline SVG) ---------- */
  function renderChart() {
    var vals = DATA.throughput;
    var W = 760, H = 190;
    var padL = 34, padR = 12, padT = 12, padB = 26;
    var plotW = W - padL - padR;
    var plotH = H - padT - padB;
    var maxV = 100;
    var step = plotW / (vals.length - 1);
    var x = function (i) { return padL + i * step; };
    var y = function (v) { return padT + (1 - v / maxV) * plotH; };

    var parts = [];

    /* horizontal gridlines + y-axis labels */
    [100, 75, 50, 25, 0].forEach(function (g) {
      var gy = y(g);
      parts.push('<line class="grid-line" x1="' + padL + '" y1="' + gy.toFixed(1) +
                 '" x2="' + (W - padR) + '" y2="' + gy.toFixed(1) + '"/>');
      parts.push('<text class="axis-label" x="' + (padL - 8) + '" y="' + (gy + 3).toFixed(1) +
                 '" text-anchor="end">' + g + '</text>');
    });

    /* x-axis hour labels every 4 hours + last point */
    var labelIdx = [0, 4, 8, 12, 16, 20, 23];
    labelIdx.forEach(function (i) {
      var lx = x(i);
      var anchor = i === 0 ? "start" : (i === 23 ? "end" : "middle");
      var hh = (i < 10 ? "0" : "") + i + ":00";
      parts.push('<text class="axis-label" x="' + lx.toFixed(1) + '" y="' + (H - 8) +
                 '" text-anchor="' + anchor + '">' + hh + '</text>');
    });

    /* area + line */
    var linePts = vals.map(function (v, i) { return x(i).toFixed(1) + "," + y(v).toFixed(1); });
    var baseline = (padT + plotH).toFixed(1);
    var areaD = "M" + x(0).toFixed(1) + "," + baseline +
                " L" + linePts.join(" L") +
                " L" + x(vals.length - 1).toFixed(1) + "," + baseline + " Z";
    parts.push('<path class="chart-area" d="' + areaD + '"/>');
    parts.push('<polyline class="chart-line" points="' + linePts.join(" ") + '"/>');

    /* peak marker + annotation */
    var peak = Math.max.apply(null, vals);
    var peakIdx = vals.indexOf(peak);
    parts.push('<circle class="chart-dot" cx="' + x(peakIdx).toFixed(1) +
               '" cy="' + y(peak).toFixed(1) + '" r="3.5"/>');
    var pkx = Math.min(x(peakIdx) - 4, W - padR - 70);
    parts.push('<text class="chart-peak-label" x="' + pkx.toFixed(1) +
               '" y="' + (y(peak) - 9).toFixed(1) + '">Peak ' + peak + 'k · 19:00</text>');

    $("throughput-chart").innerHTML = parts.join("");

    /* summary stats */
    var min = Math.min.apply(null, vals);
    var mean = vals.reduce(function (a, b) { return a + b; }, 0) / vals.length;
    var stats = [
      ["Peak", peak + "k / min"],
      ["Trough", min + "k / min"],
      ["24h mean", mean.toFixed(1) + "k / min"],
      ["Last hour", vals[vals.length - 1] + "k / min"]
    ];
    $("chart-stats").innerHTML = stats.map(function (s) {
      return '<div><div class="cstat-label">' + s[0] + '</div>' +
             '<div class="cstat-value">' + s[1] + '</div></div>';
    }).join("");
  }

  /* ---------- Filtering ---------- */
  function getVisible() {
    var q = filters.search.trim().toLowerCase();
    return incidents.filter(function (i) {
      if (filters.severity !== "all" && i.severity !== filters.severity) return false;
      if (filters.status !== "all" && i.status !== filters.status) return false;
      if (q) {
        var hay = [i.id, i.service, i.owner, i.title, i.status].join(" ").toLowerCase();
        if (hay.indexOf(q) === -1) return false;
      }
      return true;
    });
  }

  function sevBadge(sev) {
    return '<span class="sev sev--' + sev + '">' + esc(sev) + '</span>';
  }
  function statusCell(st) {
    return '<span class="status status--' + st + '"><span class="status-dot" aria-hidden="true"></span>' +
           esc(st.charAt(0).toUpperCase() + st.slice(1)) + '</span>';
  }

  function renderIncidents(restoreFocus) {
    var visible = getVisible();
    var tbody = $("incident-rows");
    var empty = $("incidents-empty");

    tbody.innerHTML = visible.map(function (i) {
      var unassigned = i.owner === "Unassigned";
      return '<tr data-id="' + esc(i.id) + '" tabindex="0" aria-selected="' +
        (i.id === selectedId) + '" class="' + (i.id === selectedId ? "is-selected" : "") + '">' +
        '<td><span class="cell-id">' + esc(i.id) + '</span>' +
            '<span class="cell-title">' + esc(i.title) + '</span></td>' +
        '<td>' + sevBadge(i.severity) + '</td>' +
        '<td><span class="cell-service">' + esc(i.service) + '</span></td>' +
        '<td class="cell-age">' + esc(i.age) + '</td>' +
        '<td><span class="cell-owner' + (unassigned ? ' is-unassigned' : '') + '">' + esc(i.owner) + '</span></td>' +
        '<td>' + statusCell(i.status) + '</td>' +
      '</tr>';
    }).join("");

    empty.hidden = visible.length !== 0;
    $("result-count").textContent = visible.length + " of " + incidents.length + " shown";

    if (restoreFocus && selectedId) {
      var row = tbody.querySelector('tr[data-id="' + selectedId + '"]');
      if (row) row.focus();
    }
  }

  /* ---------- Detail panel ---------- */
  function renderDetail() {
    var el = $("detail-content");
    var i = incidents.filter(function (x) { return x.id === selectedId; })[0];

    if (!i) {
      el.innerHTML = '<div class="detail-placeholder">' +
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="1"/><line x1="9" y1="4" x2="9" y2="20"/></svg>' +
        '<div>Select an incident to view its detail.</div></div>';
      return;
    }

    var acknowledged = i.status === "acknowledged";
    var unassigned = i.owner === "Unassigned";
    var rows = [
      ["Service", esc(i.service), ""],
      ["Severity", esc(i.severity.charAt(0).toUpperCase() + i.severity.slice(1)), ""],
      ["Age", esc(i.age), ""],
      ["Owner", esc(i.owner), unassigned ? " is-unassigned" : ""],
      ["Status", esc(i.status.charAt(0).toUpperCase() + i.status.slice(1)), ""]
    ];

